"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 freeze amendment (draft 2026-11-20): the Gemini rivals without token probabilities.

Since the afternoon of 2026-11-19 the Gemini API answers 400 "Logprobs is not enabled for this model" for
gemini-4-hydrogen and gemini-4-carbon (re-checked 2026-11-20 00:30 with one call each). Plan 6.4: "use the
probabilities as scores when available, thresholds chosen on dev in the rival's favour; otherwise use its answers".
This script applies that fallback to the stored dev responses, with no new calls:
- every setting's answers become scores (yes 1, no 0, no answer word 0.5, as p1v4_api.parse does without
  probabilities), the plan's operating-point rule (7.1) picks the thresholds, and the setting is chosen with the same
  rank as p1v4_api.choose (floors met, five-part mean, lowest floor);
- the plan's decision table (scripts/p1v4_test_report.py, unchanged) is then run on dev with these rivals and, as ours,
  the step 2b ears read-out (the proposed main system) and the old head (reference).
Outputs: data/p1v4/runs/api/<system>/answers/scores_dev_<setting>.json, results/main_v04/answer_only_dev.json,
results/main_v04/decision_dev_dryrun_{allclass_ears,l1}_answers.json.
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_answer_only_dev.py
"""
import glob
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_api as A  # noqa: E402
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_readout as RO  # noqa: E402
import p1v4_score as S  # noqa: E402
import p1v4_test_report as TR  # noqa: E402

SYSTEMS = {"B2-fast": "b2fast", "B2-strong": "b2strong", "B3": "b3"}


def choose_answers(rows, asked, sd):
    os.makedirs(os.path.join(A.OUT, sd, "answers"), exist_ok=True)
    log, best = [], None
    for d in sorted(glob.glob(os.path.join(A.OUT, sd, "*", "responses.jsonl"))):
        setting = os.path.basename(os.path.dirname(d))
        got = A.load_scores(d)
        missing = [x for x in asked if x not in got]
        if len(missing) > 0.005 * len(asked):
            continue
        sc = {}
        for pid, q in asked:
            a = got[(pid, q)].get("answer") if (pid, q) in got else None
            sc.setdefault(pid, {})[q] = 1.0 if a == "yes" else 0.0 if a == "no" else 0.5
        path = os.path.join(A.OUT, sd, "answers", f"scores_dev_{setting}.json")
        json.dump(sc, open(path, "w"))
        keyed = {tuple(k.split("|")[:2]) + (int(k.split("|")[2]),): v for k, v in sc.items()}
        res = S.operating_point(rows, keyed)
        res.update(setting=setting, missing=len(missing), path=path)
        log.append(res)
        rank = (res["floors_met"], res["primary"], res["lowest_floor"])
        if best is None or rank > best[0]:
            best = (rank, res)
    keep = ("setting", "primary", "floors_met", "lowest_floor", "th_s", "th_r", "missing")
    return {"log": [{k: e[k] for k in keep} for e in log], "chosen": {k: best[1][k] for k in keep + ("path", "parts")}}


def main():
    rows = D.load_rows("dev")
    ctx = C.Context("dev", asr="turbo")
    asked = [(f"{r['unit']}|{r['version']}|{p['k']}", a[0]) for r in rows for p in r["points"]
             for a in ctx.situation(r, p["k"], "full")[1]]
    rep = json.load(open("results/main_v04/dev_report.json"))["systems"]
    out = {}
    for name, sd in SYSTEMS.items():
        out[name] = choose_answers(rows, asked, sd)
        out[name]["with_probabilities"] = {k: rep[name]["operating_point"][k] for k in ("setting", "primary")}
        c = out[name]["chosen"]
        print(f"{name}: answers -> {c['setting']} {c['primary']:.3f} (floors met {c['floors_met']}); "
              f"with probabilities {out[name]['with_probabilities']['setting']} "
              f"{out[name]['with_probabilities']['primary']:.3f}")
    json.dump(out, open("results/main_v04/answer_only_dev.json", "w"), indent=1)
    th = json.load(open("results/main_v04/readout_allclass_dev.json"))["natural"]["all-class ears"]["th"]
    cands = {"allclass_ears": {"kind": "score", "path": f"{RO.OUT}/scores_dev_allclass_ears.json",
                               "th_s": th["S"], "th_r": th["R"]}, "l1": None}
    base = TR.dev_manifest
    for cname, entry in cands.items():
        print(f"=== ours = {cname}, Gemini rivals on answers")

        def manifest(entry=entry):
            m = base()
            for name in SYSTEMS:
                c = out[name]["chosen"]
                m[name] = {"kind": "score", "path": c["path"], "th_s": c["th_s"], "th_r": c["th_r"]}
            if entry is not None:
                m[TR.OURS] = entry
            return m
        TR.dev_manifest = manifest
        TR.run("dev", f"results/main_v04/decision_dev_dryrun_{cname}_answers.json")
    TR.dev_manifest = base


if __name__ == "__main__":
    main()
